/bin/bash -lc "node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import assert from 'node:assert/strict';
import {transformSync} from 'esbuild';
const {code} = transformSync(readFileSync('src/i18n.ts', 'utf8'), {loader: 'ts', format: 'esm'});
const {getInitialLanguage, translations, LANGUAGE_STORAGE_KEY} = await import("'`data:text/javascript;base64,${Buffer.from(code).toString('"'base64')}"'`);
const browser = (languages) => Object.defineProperty(globalThis, '"'navigator', {value: {languages}, configurable: true});
const storage = (value) => {globalThis.localStorage = {getItem: (key) => {assert.equal(key, LANGUAGE_STORAGE_KEY); return value;}};};
browser(['en-US']); storage('ru'); assert.equal(getInitialLanguage(), 'ru');
browser(['ru-RU']); storage('en'); assert.equal(getInitialLanguage(), 'en');
storage(null); assert.equal(getInitialLanguage(), 'ru');
storage('unsupported'); browser(['fr-FR', 'en-GB']); assert.equal(getInitialLanguage(), 'en');
browser(['fr-FR']); assert.equal(getInitialLanguage(), 'en');
globalThis.localStorage = {getItem: () => {throw new Error('Storage blocked');}};
browser(['ru-RU']); assert.equal(getInitialLanguage(), 'ru');
assert.deepEqual(Object.keys(translations.en).sort(), Object.keys(translations.ru).sort());
assert.ok(Object.values(translations.ru).every((text) => typeof text === 'string' && text.length > 0));
console.log('Passed: saved language priority, browser language, invalid preference, English fallback, blocked storage, complete translations.');
NODE

